class MotorMVSQL: """ Motor principal. Recibe una ConexionBD ya conectada (conectores.py) y la configuración del proveedor de IA elegido por el cliente. """ def __init__(self, conexion, ia): """ conexion: ConexionBD conectada. ia: dict {proveedor, api_key, modelo, base_url} """ self.cx = conexion self.ia = ia self.catalogo = conexion.extraer_catalogo() self.fichas = catalogo_a_fichas(self.catalogo) self.recuperador = RecuperadorEsquema(self.fichas) def _completar(self, system, user, max_tokens=1500): return completar(self.ia["proveedor"], self.ia.get("api_key"), system, user, modelo=self.ia.get("modelo"), base_url=self.ia.get("base_url"), max_tokens=max_tokens) def responder(self, pregunta, k=4, limite=5000, explicar=True, contexto="", privado=False): """ contexto: preferencias del usuario (moneda, decimales, etc.) que se pasan a la IA como instrucción adicional — no forman parte de la pregunta guardada ni del historial. privado: modo privacidad estricta. Con True, al proveedor de IA se le manda el esquema SIN valores de ejemplo de las columnas (texto_min) y no se genera análisis del resultado (explicar se fuerza a False): así NINGUN dato real de la base sale, ni al generar el SQL ni después. """ if privado: explicar = False resultado = { "pregunta": pregunta, "tablas_recuperadas": [], "sql": None, "valido": False, "problemas": [], "advertencias": [], "confianza": None, "supuestos": "", "columnas": None, "filas": None, "sql_ejecutado": None, "error": None, "explicacion": None, "usa_cte": False, } # 1) RAG relevantes, sims = self.recuperador.recuperar(pregunta, k=k) resultado["tablas_recuperadas"] = [f["tabla"] for f in relevantes] sim_top = sims[0] if sims else 0.0 # 2) generación. En modo privado se usa texto_min (sin valores de # ejemplo): al proveedor de IA solo van nombres de tablas y columnas. _clave = "texto_min" if privado else "texto" esquema = "

".join(f.get(_clave, f["texto"]) for f in relevantes) _system_sql = """Sos un experto en SQL que traduce preguntas en lenguaje natural a consultas SQL de nivel profesional. La pregunta puede venir en español, inglés o portugués. REGLAS ESTRICTAS: 1. Usá EXCLUSIVAMENTE las tablas y columnas del esquema provisto. NUNCA inventes nombres. 2. El motor es {dialecto}. Usá exactamente su sintaxis. 3. OPTIMIZACIÓN: si la consulta requiere agregaciones intermedias, subconsultas repetidas o pasos lógicos, estructurala con CTEs (WITH ... AS) con nombres descriptivos. Preferí CTE a subconsultas anidadas. Evitá SELECT *: listá solo las columnas necesarias. Filtrá lo antes posible (predicados en el WHERE más interno). Nunca apliques funciones sobre columnas indexables en el WHERE: usá rangos (col >= 'inicio' AND col < 'fin'). 4. Si la pregunta pide ranking o "top", agregá ORDER BY y limitá filas. 5. Usá JOINs explícitos según las relaciones del esquema. 6. Filtrá registros anulados/eliminados si existe la columna (anulada=0, deleted=0, activo=1). 7. Solo SELECT (o WITH ... SELECT). Nunca INSERT/UPDATE/DELETE/DROP/ALTER/EXEC. 8. Alias legibles en español para columnas calculadas (total_cobrado, promedio_mensual). FORMATO DE RESPUESTA — devolvé EXACTAMENTE esto, sin markdown ni explicación extra: SQL: <la consulta> CONFIANZA: <entero 0-100: qué tan seguro estás de que la consulta responde exactamente la pregunta con este esquema> SUPUESTOS: <si asumiste algo (interpretación de fechas, qué columna usar), listalo en una línea; si no, "ninguno"> ESQUEMA DISPONIBLE (usá solo esto): {esquema} """ system = _system_sql.format(dialecto=self.cx.dialecto, esquema=esquema) pregunta_ia = f"{pregunta}

[Preferencias del usuario: {contexto}]" if contexto else pregunta crudo = self._completar(system, pregunta_ia) sql, conf_llm, supuestos = _parsear_respuesta_sql(crudo) resultado["sql"] = sql resultado["supuestos"] = supuestos resultado["usa_cte"] = sql.lower().lstrip().startswith("with") # 3) validación es_valido, problemas, advertencias = validar_sql(sql, self.catalogo) resultado["valido"] = es_valido resultado["problemas"] = problemas resultado["advertencias"] = advertencias # 3b) reintento automático si la validación falló (self-repair) if not es_valido: arreglado = self._reintentar_sql(system, pregunta_ia, sql, problemas) if arreglado: sql, conf_llm, supuestos, advertencias = arreglado es_valido, problemas = True, [] resultado.update(sql=sql, supuestos=supuestos, valido=True, problemas=[], advertencias=advertencias, usa_cte=sql.lower().lstrip().startswith("with")) # 4) confianza resultado["confianza"] = calcular_confianza( conf_llm, sim_top, es_valido, len(resultado["advertencias"]), resultado["usa_cte"]) # 5) ejecución if es_valido: try: cols, filas, sql_exec = self.cx.ejecutar(sql, limite=limite) resultado["columnas"] = cols resultado["filas"] = filas resultado["sql_ejecutado"] = sql_exec except Exception as e: resultado["error"] = str(e) # 6) explicación en lenguaje natural if explicar and resultado["filas"] is not None: resultado["explicacion"] = self._explicar_resultado( pre

