def _explicar_resultado(self, pregunta, sql, resultado, contexto): """Explicación en lenguaje natural de lo que dice el dato. Devuelve None si falla: la explicación es un extra, nunca puede tumbar una consulta que ya se ejecutó bien. """ try: muestra = _muestra_texto(resultado["columnas"], resultado["filas"]) extra = f"

PREFERENCIAS DEL USUARIO: {contexto}" if contexto else "" _system_explicar = ("Sos un analista de datos. Te paso una pregunta de un " "usuario de negocio, el SQL ejecutado y una muestra del resultado. " "Explicá el resultado en 2-4 frases claras en el MISMO idioma de la " "pregunta, con números concretos. No expliques el SQL: explicá QUÉ dice " "el dato. Si el resultado está vacío, decilo y sugerí por qué puede ser.") return self._completar( _system_explicar, f"PREGUNTA: {pregunta}

SQL:
{sql}

RESULTADO ({len(resultado['filas'])} filas):
{muestra}{extra}", max_tokens=400) except Exception: return None

