async function answer(question, ai, { run, k = 4, limit = 5000, explain = true }) { if (!CATALOG) throw new Error("Conectá una base de datos primero."); const { cards, simTop } = retrieve(question, k); const schema = cards.map((c) => c.texto).join("

"); const system = SYSTEM_SQL(DIALECT, schema); let { sql, confLLM, assumptions } = parseResponse(await complete(ai, system, question)); let { valid, problems, warnings } = validate(sql, CATALOG); // self-repair: un reintento con los errores del validador if (!valid) { try { const fix = `${question}

Tu consulta anterior fue:
${sql}

Fue RECHAZADA por:
- ${problems.join("
- ")}
Generá una consulta corregida usando SOLO tablas y columnas del esquema.`; const retry = parseResponse(await complete(ai, system, fix)); const revalid = validate(retry.sql, CATALOG); if (revalid.valid) { ({ sql, confLLM, assumptions } = retry); ({ valid, problems, warnings } = revalid); } } catch { /* reintento best-effort */ } } const usesCte = sql.trimStart().toLowerCase().startsWith("with"); const result = { pregunta: question, tablas: cards.map((c) => c.tabla), sql, valido: valid, problemas: problems, advertencias: warnings, supuestos: assumptions, confianza: confidence(confLLM, simTop, valid, warnings.length, usesCte), columnas: null, filas: null, sqlEjecutado: null, ms: null, error: null, explicacion: null, }; if (valid) { try { const r = await run(sql, limit); Object.assign(result, { columnas: r.columns, filas: r.rows, sqlEjecutado: r.sql, ms: r.ms }); } catch (e) { result.error = e.message; } } if (explain && result.filas) { try { const sample = [result.columnas.join(" | "), ...result.filas.slice(0, 20).map((f) => f.join(" | "))].join("
"); result.explicacion = await complete(ai, SYSTEM_EXPLAIN, `PREGUNTA: ${question}

SQL:
${sql}

RESULTADO (${result.filas.length} filas):
${sample}`, 400); } catch { /* la explicación es opcional */ } } return result; }

