== Trial y licencia del desktop (Electron) =="); await test("primer arranque: entra, con los 7 días completos", () => { const dirs = entorno(); const r = lic.verificarAcceso(dirs); assert.strictEqual(r.permitido, true); assert.strictEqual(r.diasRestantes, 7); assert.strictEqual(r.conLicencia, false); }); await test("el primer arranque deja la marca (si no, el trial no arranca nunca)", () => { const dirs = entorno(); lic.verificarAcceso(dirs); assert.ok(fs.existsSync(path.join(dirs.datos, ".mvsql_trial.json")), "no se escribió la marca: cada arranque volvería a dar 7 días"); }); await test("a mitad del trial descuenta los días transcurridos", () => { const dirs = entorno(); marcaTrial(dirs, 3); const r = lic.verificarAcceso(dirs); assert.strictEqual(r.permitido, true); assert.strictEqual(r.diasRestantes, 4); }); await test("EL TRIAL SE ACABA: al día 7 ya no entra", () => { const dirs = entorno(); marcaTrial(dirs, 7); const r = lic.verificarAcceso(dirs); assert.strictEqual(r.permitido, false, "el trial no corta: es una licencia perpetua gratis"); assert.strictEqual(r.diasRestantes, 0); }); await test("y sigue cortado mucho después", () => { const dirs = entorno(); marcaTrial(dirs, 400); assert.strictEqual(lic.verificarAcceso(dirs).permitido, false); }); await test("editar la fecha a mano NO estira el trial (firma inválida)", () => { const dirs = entorno(); // El tramposo se pone una fecha de inicio en el futuro para tener más días. fs.writeFileSync(path.join(dirs.datos, ".mvsql_trial.json"), JSON.stringify( { inicio: new Date(Date.now() + 90 * DIA).toISOString(), firma: "firma-inventada" })); const r = lic.verificarAcceso(dirs); // Se descarta y arranca un trial nuevo: 7 días, no 97. assert.strictEqual(r.diasRestantes, 7); const guardado = JSON.parse(fs.readFileSync(path.join(dirs.datos, ".mvsql_trial.json"), "utf8")); assert.strictEqual(guardado.firma, lic._firma(guardado.inicio), "quedó una marca sin firma válida"); }); await test("atrasar el reloj no revive el tria